state-management.code-example:
terraform {
  backend "s3" {
    bucket         = "my-terraform-state"
    key            = "prod/app/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-lock"
    encrypt        = true
  }
}

module-patterns.code-example:
module "app_service" {
  source  = "./modules/ecs-service"
  version = "1.2.0"

  name          = "my-api"
  image         = "${var.ecr_repo}:${var.image_tag}"
  cpu           = 512
  memory        = 1024
  desired_count = var.environment == "prod" ? 3 : 1

  environment_variables = {
    APP_ENV = var.environment
    # Secrets injected from Secrets Manager, not here
  }
}

readiness-probe.code-example:
app.get('/ready', async (req, res) => {
  const checks = {
    database: await checkDb(),
    cache: await checkCache(),
  };
  const healthy = Object.values(checks).every(c => c.ok);
  res.status(healthy ? 200 : 503).json({ status: healthy ? 'ready' : 'degraded', checks });
});

graceful-shutdown.code-example:
process.on('SIGTERM', async () => {
  logger.info('SIGTERM received, starting graceful shutdown');
  server.close(async () => {
    await db.disconnect();
    logger.info('Graceful shutdown complete');
    process.exit(0);
  });
  // Force exit if drain takes too long
  setTimeout(() => process.exit(1), 25000);
});
